"use client"; import { useRoundHistory } from "../../lib/hooks/useBlobbyApi"; import { Card } from "../ui/Card"; import { Badge } from "../ui/Badge"; export function RoundHistory(){const q=useRoundHistory(); const rows=(q.data as any)?.data||[]; return <Card><h3 className="display-text text-2xl">Round History</h3><div className="mt-4 grid gap-3">{rows.map((r:any)=><div key={String(r.id)} className="rounded-2xl border-2 border-[#020202] bg-white p-4 sm:flex sm:items-center sm:justify-between"><b>Round {String(r.id)}</b><span>{r.eligibleTicketCount} tickets</span><Badge>{r.status}</Badge></div>)}</div></Card>}
