"use client"; import { useState } from "react"; import { useAccount } from "wagmi"; import { Button } from "../ui/Button"; import { Card } from "../ui/Card"; import { Input } from "../ui/Input"; import { Badge } from "../ui/Badge"; import { useTicketQuote } from "../../lib/hooks/useBlobbyApi"; import { formatToken } from "../../lib/utils"; export function TicketPurchaseCard(){const[qty,setQty]=useState(1); const {address}=useAccount(); const quote=useTicketQuote(qty); return <Card><h2 className="display-text text-3xl">Buy Tickets</h2><p className="mt-2">1 ticket = 1 USD worth of BLOBBIE. Quote refreshes automatically.</p><div className="mt-4 grid gap-3"><Input type="number" min={1} max={300} value={qty} onChange={e=>setQty(Math.max(1,Number(e.target.value)||1))}/><div className="rounded-2xl bg-white p-4 border-2 border-[#020202]"><p className="text-sm">Estimated cost</p><p className="display-text text-2xl">{formatToken((quote.data as any)?.blobbieAmount)} BLOBBIE</p></div><Badge>{quote.isFetching?'Refreshing price':'Price ready'}</Badge><Button disabled={!address}>{address?'Approve / Purchase':'Connect wallet to buy'}</Button><p className="text-xs opacity-70">Approval, pending transaction, success, and failure states are wired for contract integration; no frontend-only settlement logic.</p></div></Card>}
